import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.DBU8LMUS.js";const d=JSON.parse('{"title":"Galeri Kegiatan","description":"","frontmatter":{"title":"Galeri Kegiatan","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/galeri.md","filePath":"latest/galeri.md","lastUpdated":1786334463000}'),o={name:"latest/galeri.md"};function l(r,a,g,s,u,h){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="galeri-kegiatan" tabindex="-1">Galeri Kegiatan <a class="header-anchor" href="#galeri-kegiatan" aria-label="Permalink to &quot;Galeri Kegiatan&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Galeri Kegiatan</strong> adalah tempat berbagi foto dokumentasi acara dan kegiatan ILUNI FT ELEKTRO UNPAK. Foto diunggah setelah dikompresi otomatis agar hemat penyimpanan, lalu dapat dilihat semua pengguna.</p><h2 id="melihat-galeri" tabindex="-1">Melihat Galeri <a class="header-anchor" href="#melihat-galeri" aria-label="Permalink to &quot;Melihat Galeri&quot;">​</a></h2><ol><li>Klik menu <strong>Galeri</strong> pada navigasi.</li><li>Halaman menampilkan kisi-kisi (grid) foto kegiatan.</li><li>Klik foto untuk melihatnya dalam tampilan besar (lightbox).</li></ol><h3 id="menjelajah-foto" tabindex="-1">Menjelajah Foto <a class="header-anchor" href="#menjelajah-foto" aria-label="Permalink to &quot;Menjelajah Foto&quot;">​</a></h3><ul><li>Gunakan tombol panah atau geser untuk berpindah antar foto dalam tampilan besar.</li><li>Tutup tampilan besar dengan menekan tombol <strong>Tutup</strong> atau tombol <strong>Esc</strong>.</li></ul><h2 id="mengunggah-foto" tabindex="-1">Mengunggah Foto <a class="header-anchor" href="#mengunggah-foto" aria-label="Permalink to &quot;Mengunggah Foto&quot;">​</a></h2><h3 id="membuka-formulir-unggah" tabindex="-1">Membuka Formulir Unggah <a class="header-anchor" href="#membuka-formulir-unggah" aria-label="Permalink to &quot;Membuka Formulir Unggah&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk.</li><li>Klik tombol <strong>Unggah Foto</strong> pada halaman <strong>Galeri</strong>.</li><li>Pilih satu atau beberapa foto dari perangkat Anda.</li></ol><h3 id="proses-unggah" tabindex="-1">Proses Unggah <a class="header-anchor" href="#proses-unggah" aria-label="Permalink to &quot;Proses Unggah&quot;">​</a></h3><ol><li>Foto dipilih dari perangkat (format gambar standar: JPG, PNG, WebP).</li><li>Foto <strong>dikompresi dan diubah ukurannya otomatis</strong> (maksimal 1280 piksel, kualitas 85%) sebelum diunggah.</li><li>Isi <strong>keterangan/caption</strong> (opsional) untuk foto.</li><li>Klik <strong>Unggah</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Kualitas Foto</p><p>Karena foto dikompresi otomatis, unggahlah foto asli yang cukup besar agar hasil tampilan tetap tajam setelah diperkecil.</p></div><h2 id="menghapus-foto" tabindex="-1">Menghapus Foto <a class="header-anchor" href="#menghapus-foto" aria-label="Permalink to &quot;Menghapus Foto&quot;">​</a></h2><p>Foto dapat dihapus oleh:</p><ul><li><strong>Pengunggah</strong> foto.</li><li><strong>Admin</strong> dengan kemampuan <code>moderate_gallery</code>.</li><li><strong>Super admin</strong>.</li></ul><ol><li>Buka foto yang ingin dihapus.</li><li>Klik tombol <strong>Hapus</strong> (jika tersedia untuk Anda).</li><li>Konfirmasi penghapusan.</li></ol><p>Penghapusan menghilangkan foto dari galeri beserta berkasnya di penyimpanan.</p><h2 id="etika-berbagi-foto" tabindex="-1">Etika Berbagi Foto <a class="header-anchor" href="#etika-berbagi-foto" aria-label="Permalink to &quot;Etika Berbagi Foto&quot;">​</a></h2><ul><li>Unggah hanya foto yang relevan dengan kegiatan komunitas.</li><li>Hormati privasi: mintalah izin jika foto memuat orang lain secara jelas.</li><li>Jangan mengunggah konten yang melanggar aturan komunitas.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/peringkat">Peringkat Kontribusi</a> untuk melihat papan peringkat anggota.</p>',21)])])}const p=e(o,[["render",l]]);export{d as __pageData,p as default};
